import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
import { noop } from '@salesforce/retail-react-app/app/utils/utils';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useHistory } from 'react-router-dom';
import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
import { useContentfulClient } from 'app/hooks/useContentfulClient';
import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
import { FooterNavColumn } from './footerNavColumn';
import { BottomBar } from './bottomBar';

const ZIMM_FOOTER_RECIPE = 'ZimmFooter';

// Contentful resolves nested references `include` levels deep, and the footer model is exactly
// three: footerConfig → navGroups (1) → links (2) → regions (3). Depth 3 is the minimum that
// populates `entry.fields.regions[].fields.siteId`, which isEligible reads.
//
// Getting this wrong fails hard, not gracefully. At 2, a region-scoped link's `regions` array
// arrives as unresolved link stubs with no `fields` (the SDK keeps unresolvable links by default
// — `withoutUnresolvableLinks` is not passed), so `region.fields.siteId` throws, the `.catch`
// below swallows it, footerData stays null and the *entire* footer renders nothing — columns,
// logo band and bottom bar included. Not a house default either: useContentful.ts hardcodes 2
// for asset resolution, per its own comments, which is a different concern.
const FOOTER_INCLUDE_DEPTH = 3;

